#include <iostream>
using namespace std;

int main() {
    int n, total = 0, value, count = 0;
    cin >> n;
    ++n;

    for (int i = 0; i < n - 1; ++i) {
        cin >> value;
        total += value;
    }

    for (int i = 1; i <= 5; ++i) {
        if ((i + total) % n != 1)
            ++count;
    }

    cout << count << '\n';
    return 0;
}

